import string
import random


def task_func(text, seed=None):
    if not text:
        raise ValueError("Input text cannot be empty.")

    if seed is not None:
        random.seed(seed)

    def replace_char(char):
        if char.isalpha():
            return random.choice(string.ascii_lowercase)
        elif char.isdigit():
            return str(random.randint(0, 9))
        elif char.isspace():
            return random.choice([str(random.randint(0, 9)), random.choice(string.ascii_lowercase)])
        else:
            return char

    return ''.join(replace_char(char) for char in text)
